with base as (select *, last_day(opened_date) as opened_date_month_end from stores where sqft is null), stores_stats as (select date_trunc('MONTH', opened_date_month_end) as opened_month_end_month, max(sqft) - min(sqft) as sqft_range from base group by date_trunc('MONTH', opened_date_month_end)) select opened_month_end_month, sqft_range from stores_stats order by opened_month_end_month desc limit 1;
